                    transcript = (self._quote(self._seed_text(name), style)
                                  + "\n\n" + self._FILLER)
                    by_id = self._score(name, transcript)
                    self.assertFalse(by_id["cites-both-facts"]["passed"],
                                     f"{name}/{style}: quoted seed material "
                                     "supplied the facts")

